{
  label: "変わったことの技術の手引きの節は、書いた順に、指した先のタブ・タブの中の位置・題になる",
  actual: () => primerPositionsIn(impactOf({ changed: changedWithPrimers(["d", "b"]) })),
  expected: [{ tab: "codebase", index: 1, label: "D" }, { tab: "language", index: 1, label: "B" }],
},

{
  label: "primers に無い id は、変わったことの技術の手引きの節に入れない",
  actual: () => primerPositionsIn(impactOf({ changed: changedWithPrimers(["ghost", "b"]) })),
  expected: [{ tab: "language", index: 1, label: "B" }],
},

{
  label: "primers に無い id は、増えた状況の技術の手引きの節にも入れない",
  actual: () => primerPositionsIn(impactOf({ added: [addedWithPrimers(["ghost", "b"])] })),
  expected: [{ tab: "language", index: 1, label: "B" }],
},

{
  label: "増えた状況の技術の手引きの節も、書いた順に、指した先のタブ・タブの中の位置・題になる",
  actual: () => primerPositionsIn(impactOf({ added: [addedWithPrimers(["d", "a"])] })),
  expected: [{ tab: "codebase", index: 1, label: "D" }, { tab: "language", index: 0, label: "A" }],
},

{
  label: "増えた状況が 2 つ以上あるとき、どの増えた状況も自分が書いた技術の手引きの節を引く",
  actual: () => topicsWithPrimersOf(impactOf({ added: [addedOf("増えた 1"), addedWithPrimers(["d"])] }))[1].primers,
  expected: [{ tab: "codebase", index: 1, label: "D" }],
},

{
  label: "技術の手引きの節を書いていない変わったこと・増えた状況では、技術の手引きの節の並びは空",
  actual: () => topicsWithPrimersOf(impactOf({ changed: changedWithPrimers(undefined), added: [addedOf("増えた")] })).map((topic) => topic.primers),
  expected: [[], []],
},

{
  label: "変わったことの技術の手引きの節(primers)が文字列なら、理由はその道筋",
  actual: () => shapeReasonOf({ impact: impactOf({ changed: changedWithPrimers("a") }) }),
  expected: { kind: "shape", key: "impact.changed.primers" },
},

{
  label: "増えた状況の技術の手引きの節の要素が文字列でなければ、理由はその道筋",
  actual: () => shapeReasonOf({ impact: impactOf({ added: [addedWithPrimers([5])] }) }),
  expected: { kind: "shape", key: "impact.added[].primers" },
},

/** 今のタブをそのタブにし、そのタブの覚えた位置(本文の欄とページ全体)を戻す(初めてなら先頭)。離れるタブの位置は覚えない。 */
const restoreTab = (tab) => {
  currentTab = tab;
  renderTab();
  main.scrollTop = saved[tab].main;
  window.scrollTo(0, saved[tab].page);
};

/** この画面の中でタブを切り替える。離れるタブの位置(本文の欄とページ全体)を覚えてから、戻るタブの位置を戻す。 */
const showTab = (tab) => {
  if (tab === currentTab) return;
  saved = { ...saved, [currentTab]: { main: main.scrollTop, page: window.scrollY } };
  restoreTab(tab);
};
